import React, { useEffect, useState } from 'react';
import { useNavigate } from 'react-router-dom';
import './Profile.css';

const Profile = ({ onModuleChange }) => {
  const [user, setUser] = useState({ name: '', email: '' });
  const [editMode, setEditMode] = useState(false);
  const [form, setForm] = useState({ name: '', email: '' });
  const [message, setMessage] = useState('');
  const [savedRecipes, setSavedRecipes] = useState([]);
  const [loadingRecipe, setLoadingRecipe] = useState(null);
  const navigate = useNavigate();

  // Only call onModuleChange('profile') on mount
  useEffect(() => {
    if (onModuleChange) onModuleChange('profile');

    const token = localStorage.getItem('token');
    if (!token) return;

    // Fetch current user info
    fetch('http://localhost:5000/api/users/me', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(res => res.json())
      .then(data => {
        if (data && (data.name || data.email)) {
          setUser({ name: data.name || '', email: data.email || '' });
          setForm({ name: data.name || '', email: data.email || '' });
        }
      })
      .catch(() => setMessage('Failed to fetch user details'));

    // Fetch saved recipes for the user from your DB table
    fetch('http://localhost:5000/api/users/saved-recipes', {
      headers: { Authorization: `Bearer ${token}` }
    })
      .then(async (res) => {
        // try to parse json; if backend returns non-200, still try to parse helpful body
        const data = await res.json().catch(() => null);
        return { ok: res.ok, data };
      })
      .then(({ ok, data }) => {
        if (!ok || !data) {
          setSavedRecipes([]);
          return;
        }

        // Normalize several possible backend response shapes:
        // 1) an array of saved entries: [{ _id, recipe: {...} }, ...]
        // 2) an object { saved: [...] }
        // 3) direct array of recipe objects: [{ _id, dish_name, ...}, ...]
        // 4) object { savedRecipes: [...] } (just in case)
        let arr = [];

        if (Array.isArray(data)) {
          // If array items already contain `.recipe`, keep as saved entries
          if (data.length > 0 && data[0].recipe) {
            arr = data.map(item => {
              return {
                _id: item._id || (item.recipe && (item.recipe._id || item.recipe.id)) || undefined,
                recipe: item.recipe || {}
              };
            });
          } else {
            // array of raw recipe objects
            arr = data.map(item => ({
              _id: item._id || item.id || undefined,
              recipe: item
            }));
          }
        } else if (Array.isArray(data.saved)) {
          // shape: { saved: [...] }
          arr = data.saved.map(item => ({
            _id: item._id || (item.recipe && (item.recipe._id || item.recipe.id)) || undefined,
            recipe: item.recipe || item
          }));
        } else if (Array.isArray(data.savedRecipes)) {
          arr = data.savedRecipes.map(item => ({
            _id: item._id || (item.recipe && (item.recipe._id || item.recipe.id)) || undefined,
            recipe: item.recipe || item
          }));
        } else {
          // Unknown shape: try to coerce single object into array (e.g., { recipe: {...} })
          if (data.recipe) {
            arr = [{
              _id: data._id || data.recipe._id || data.recipe.id,
              recipe: data.recipe
            }];
          } else {
            arr = [];
          }
        }

        setSavedRecipes(arr);
      })
      .catch(() => setSavedRecipes([]));
    // eslint-disable-next-line
  }, []);

  const handleChange = (e) => {
    setForm({ ...form, [e.target.name]: e.target.value });
  };

  const handleEdit = () => {
    setEditMode(true);
    setMessage('');
  };

  const handleCancel = () => {
    setEditMode(false);
    setForm({ name: user.name, email: user.email });
    setMessage('');
  };

  const handleSave = async (e) => {
    e.preventDefault();
    setMessage('');
    const token = localStorage.getItem('token');
    try {
      const res = await fetch('http://localhost:5000/api/users/update', {
        method: 'PUT',
        headers: {
          'Content-Type': 'application/json',
          Authorization: `Bearer ${token}`
        },
        body: JSON.stringify(form)
      });
      const data = await res.json();
      if (!res.ok) {
        setMessage(data.message || 'Failed to update');
        return;
      }
      setUser({ name: data.name, email: data.email });
      setEditMode(false);
      setMessage('Profile updated successfully!');
    } catch {
      setMessage('Server error');
    }
  };

  /**
   * When a saved recipe is selected:
   * - If the saved item already contains full recipe details -> use it.
   * - Else try to fetch full details by id (preferred) or fallback to dish_name POST.
   * - Save full recipe to localStorage.selectedRecipe and navigate to /results.
   *
   * Note: we keep behaviour and routes unchanged elsewhere.
   */
  const handleRecipeSelected = async (savedItem) => {
    // savedItem may be: { _id, recipe: {...} } or just recipe object
    const recipeObj = savedItem.recipe || savedItem;
    const recipeKey = savedItem._id || recipeObj._id || recipeObj.id || recipeObj.dish_name || recipeObj.name || Math.random().toString(36).slice(2);
    setLoadingRecipe(recipeKey);

    try {
      let recipeDetails = null;

      // If recipeObj already looks like a full recipe (has ingredients or instructions), use it directly
      const hasFullDetails = Array.isArray(recipeObj.ingredients) || recipeObj.instructions || recipeObj.steps;
      if (hasFullDetails) {
        recipeDetails = recipeObj;
      } else {
        // Try to fetch by id first (most reliable)
        const id = recipeObj._id || recipeObj.id || savedItem._id;
        if (id) {
          // Your recipe service endpoint (existing usage) is at port 8000
          const res = await fetch(`http://localhost:8000/recipe/${encodeURIComponent(id)}`);
          if (!res.ok) throw new Error('Failed to fetch recipe by id');
          recipeDetails = await res.json();
        } else if (recipeObj.dish_name) {
          // Fallback: POST /get_recipe
          const res = await fetch('http://localhost:8000/get_recipe', {
            method: 'POST',
            headers: { 'Content-Type': 'application/json' },
            body: JSON.stringify({ query: recipeObj.dish_name })
          });
          if (!res.ok) throw new Error('Failed to fetch recipe by name');
          recipeDetails = await res.json();
        }
      }

      if (!recipeDetails) throw new Error('No recipe details found');

      // store so /results route can pick it up (your App already reads localStorage.selectedRecipe)
      localStorage.setItem('selectedRecipe', JSON.stringify(recipeDetails));
      setLoadingRecipe(null);

      // navigate to /results (your existing RecipeResults component will read the saved recipe)
      navigate('/results');
    } catch (err) {
      console.error('Failed to load recipe details for viewing:', err);
      setLoadingRecipe(null);
      alert('Failed to fetch recipe details.');
    }
  };

  return (
    <div className="profile-page">
      {/* Hero Section */}
      <div className="profile-hero">
        <div className="container">
          <div className="profile-header">
            <div className="profile-avatar">
              {user.name ? user.name.charAt(0).toUpperCase() : 'U'}
            </div>
            <div className="profile-info">
              <h1>{user.name}</h1>
              <p>{user.email}</p>
            </div>
            {!editMode && (
              <button className="btn-edit" onClick={handleEdit}>
                ✏️ Edit Profile
              </button>
            )}
          </div>
        </div>
      </div>

      <div className="container">
        {editMode ? (
          <div className="edit-profile-form card">
            <h2>Edit Profile</h2>
            <form onSubmit={handleSave}>
              <div className="form-group">
                <label>Name</label>
                <input
                  type="text"
                  name="name"
                  value={form.name}
                  onChange={handleChange}
                  required
                />
              </div>
              <div className="form-group">
                <label>Email</label>
                <input
                  type="email"
                  name="email"
                  value={form.email}
                  onChange={handleChange}
                  required
                />
              </div>
              {message && (
                <div className={`message ${message.toLowerCase().includes('success') ? 'success' : 'error'}`}>
                  {message}
                </div>
              )}
              <div className="form-actions">
                <button type="submit" className="btn-save">
                  Save Changes
                </button>
                <button type="button" className="btn-cancel" onClick={handleCancel}>
                  Cancel
                </button>
              </div>
            </form>
          </div>
        ) : (
          <div className="profile-content">
            {/* Stats Cards */}
            <div className="stats-grid">
              <div className="stat-card">
                <div className="stat-value">{savedRecipes.length}</div>
                <div className="stat-label">Saved Recipes</div>
              </div>
              <div className="stat-card">
                <div className="stat-value">4.8</div>
                <div className="stat-label">Avg Rating</div>
              </div>
              <div className="stat-card">
                <div className="stat-value">12</div>
                <div className="stat-label">Cooked</div>
              </div>
            </div>

            {/* Saved Recipes Section */}
            <section className="saved-recipes-section">
              <h2>My Recipe Collection</h2>
              {savedRecipes.length === 0 ? (
                <div className="empty-state">
                  <span className="empty-icon">📝</span>
                  <p>No saved recipes yet. Start exploring and save your favorites!</p>
                </div>
              ) : (
                <div className="recipes-grid">
                  {savedRecipes.map((item, idx) => {
                    const recipe = item.recipe || item;
                    const recipeKey = item._id || recipe._id || recipe.id || recipe.dish_name || recipe.name || idx;
                    return (
                      <div key={item._id || idx} className="recipe-card">
                        <div className="recipe-card-content">
                          <div className="recipe-type-badge">
                            {recipe.type || 'Recipe'}
                          </div>
                          <h3>{recipe.dish_name || recipe.name}</h3>
                          <div className="recipe-meta">
                            <span>
                              <i className="meta-icon">🌍</i>
                              {recipe.cuisine || 'N/A'}
                            </span>
                            <span>
                              <i className="meta-icon">👥</i>
                              {recipe.servings_scaled_to || recipe.servings || 'N/A'} servings
                            </span>
                            <span>
                              <i className="meta-icon">⏱️</i>
                              {recipe.time_to_prepare_minutes ? `${recipe.time_to_prepare_minutes} min` : 'N/A'}
                            </span>
                          </div>
                          <button
                            className="view-recipe-btn"
                            onClick={() => handleRecipeSelected(item)}
                            disabled={loadingRecipe === recipeKey}
                          >
                            {loadingRecipe === recipeKey ? 'Loading...' : 'View Recipe →'}
                          </button>
                        </div>
                      </div>
                    );
                  })}
                </div>
              )}
            </section>
          </div>
        )}
      </div>
    </div>
  );
};

export default Profile;
